_dde_completions_node_flag_state() {
  case "$1:$2" in
    0:--help|0:-h) return 0 ;;
    0:--version|0:-v) return 0 ;;
    1:--help|1:-h) return 0 ;;
    2:--help|2:-h) return 0 ;;
    3:--help|3:-h) return 0 ;;
    3:--restart|3:-r) return 0 ;;
    4:--help|4:-h) return 0 ;;
    5:--help|5:-h) return 0 ;;
    5:--all|5:-a) return 0 ;;
    5:--restart|5:-r) return 0 ;;
    6:--working-dir|6:-w) return 2 ;;
    6:--service|6:-s) return 2 ;;
    6:--help|6:-h) return 0 ;;
    6:--run|6:-r) return 0 ;;
    6:--root|6:-o) return 0 ;;
    6:--default-working-dir|6:-d) return 0 ;;
    7:--working-dir|7:-w) return 2 ;;
    7:--service|7:-s) return 2 ;;
    7:--help|7:-h) return 0 ;;
    7:--run|7:-r) return 0 ;;
    7:--root|7:-o) return 0 ;;
    7:--default-working-dir|7:-d) return 0 ;;
    7:--no-tty|7:-T) return 0 ;;
    8:--service|8:-s) return 2 ;;
    8:--help|8:-h) return 0 ;;
  esac

  return 1
}

_dde_completions_option_seen() {
  local completed_option option_name
  for completed_option in "${completed_options[@]}"; do
    for option_name in "$@"; do
      [[ "$completed_option" == "$option_name" ]] && return 0
    done
  done

  return 1
}

_dde_completions_resolve_node() {
  node_id=0
  node_word_count=0
  positional_index=0

  local word
  for word in "${non_options[@]}"; do
    case "$node_id:$word" in
      0:init)
        node_id=1
        node_word_count=1
        ;;
      0:list)
        node_id=2
        node_word_count=1
        ;;
      0:start)
        node_id=3
        node_word_count=1
        ;;
      0:restart)
        node_id=4
        node_word_count=1
        ;;
      0:build)
        node_id=5
        node_word_count=1
        ;;
      0:bash)
        node_id=6
        node_word_count=1
        ;;
      0:command)
        node_id=7
        node_word_count=1
        ;;
      0:test)
        node_id=8
        node_word_count=1
        ;;
      *)
        break
        ;;
    esac
  done

  positional_index=$((${#non_options[@]} - node_word_count))
}

